// @ts-nocheck -- route search types are generated by the embedded app.
import { useEffect, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { createFileRoute, Link, useRouter } from "@tanstack/react-router";
import { MreTable } from "@/features/audit/learner-log-pro-copy/components/MreTable";
import {
  getActivityAnnotation,
  getAttendanceSession,
  getLearnerActivities,
  saveActivityAnnotation,
} from "@/features/audit/learner-log-pro-copy/lib/api";

export const Route = createFileRoute("/activity")({
  validateSearch: (search: Record<string, unknown>) => ({
    learner: typeof search.learner === "string" ? search.learner : "",
    activity: typeof search.activity === "string" ? search.activity : "",
  }),
  component: ActivityLogPage,
});

// Colour the KSB code badge by its type: Knowledge / Skill / Behaviour.
function ksbBadgeClass(type: string) {
  switch ((type || "").toUpperCase()) {
    case "K":
      return "bg-primary/15 text-primary";
    case "S":
      return "bg-success/15 text-success";
    case "B":
      return "bg-amber-500/15 text-amber-600";
    default:
      return "bg-muted text-muted-foreground";
  }
}

function formatDateTime(value: string | null) {
  if (!value) return null;
  const parsed = new Date(value.replace(" ", "T"));
  if (Number.isNaN(parsed.getTime())) return value;
  return parsed.toLocaleString("en-GB", {
    day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit",
  });
}

function ActivityLogPage() {
  const router = useRouter();
  const { learner, activity: activityId } = Route.useSearch();
  const overview = useQuery({
    // When an activity id (component id) is passed, show that specific activity;
    // otherwise fall back to the learner's first activity.
    queryKey: ["activity-overview", learner, activityId],
    queryFn: () => getLearnerActivities({ learner: learner || undefined, search: activityId || "", limit: 1, offset: 0 }),
  });
  const activity = overview.data?.items[0];
  const component = activity?.plan_id;

  // Attendance rows represent a live session; the preview panel shows that
  // session's recordings and the records table shows everyone who attended it.
  const isAttendance = Boolean(
    activity && (activity.activity_category === "attendance" || activity.delivery_method === "attendance"),
  );
  const session = useQuery({
    queryKey: ["attendance-session", component],
    queryFn: () => getAttendanceSession(component as string),
    enabled: Boolean(isAttendance && component),
  });
  const recordings = session.data?.recordings ?? [];

  // Auditor-entered KSBs + planned hours for this activity (saved per component).
  const queryClient = useQueryClient();
  const annotation = useQuery({
    queryKey: ["activity-annotation", component],
    queryFn: () => getActivityAnnotation(component as string),
    enabled: Boolean(component),
  });

  const [ksbsInput, setKsbsInput] = useState("");
  const [plannedInput, setPlannedInput] = useState("");
  const [editorInput, setEditorInput] = useState("");

  // Re-seed the edit fields when the activity changes or its saved data loads.
  useEffect(() => {
    if (!component) return;
    const saved = annotation.data;
    setKsbsInput(saved?.mapped_ksbs ?? "");
    setPlannedInput(
      saved?.planned_hours != null
        ? String(saved.planned_hours)
        : activity?.planned_hours != null
        ? String(activity.planned_hours)
        : "",
    );
    setEditorInput(saved?.updated_by ?? "");
  }, [component, annotation.data, activity?.planned_hours]);

  const saveAnnotation = useMutation({
    mutationFn: () =>
      saveActivityAnnotation({
        component_id: component as string,
        planned_hours: plannedInput === "" ? null : Number(plannedInput),
        mapped_ksbs: ksbsInput.trim() || null,
        updated_by: editorInput.trim() || null,
      }),
    onSuccess: (data) => queryClient.setQueryData(["activity-annotation", component], data),
  });

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="mx-auto flex max-w-[88rem] flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Live off-the-job activity</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            {activity && <span className="font-mono">{activity.month_unit}</span>}
            <button type="button" onClick={() => router.history.back()} className="font-medium text-foreground hover:underline">← Back</button>
            <Link to="/search" className="font-medium text-foreground hover:underline">Search</Link>
            <Link
              to="/journal"
              search={{
                learner: learner || activity?.learner.toLowerCase() || "",
                period: activity?.activity_period || "",
              }}
              className="font-medium text-foreground hover:underline"
            >
              Monthly journal →
            </Link>
            <span className="rounded-sm border border-success/40 bg-success/10 px-2 py-1 font-semibold text-success">Live data</span>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-[88rem] space-y-6 px-6 py-8">
        {overview.isLoading && (
          <div className="rounded-lg border border-border bg-card px-7 py-16 text-center text-sm text-muted-foreground">Loading activity from Neon…</div>
        )}
        {overview.isError && (
          <div className="rounded-lg border border-border bg-card px-7 py-16 text-center text-sm text-destructive">
            {overview.error instanceof Error ? overview.error.message : "Could not load activity."}
          </div>
        )}
        {activity && (
          <div className="grid gap-6 lg:grid-cols-3">
            <article className="rounded-lg border border-border bg-card shadow-panel lg:col-span-2">
              <header className="border-b border-border px-7 py-6">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="rounded-sm bg-primary px-2 py-1 text-xs font-semibold text-primary-foreground">{activity.activity_category}</span>
                  <span className="label-caps">{activity.plan_id}</span>
                </div>
                <h1 className="mt-3 font-serif text-2xl text-foreground">{activity.activity_unit}</h1>
              </header>
              <div className="space-y-6 px-7 py-6">
                {isAttendance && (
                  <section>
                    <div className="flex items-center justify-between">
                      <h2 className="label-caps">Session recordings</h2>
                      <span className="text-xs text-muted-foreground">
                        {session.isLoading
                          ? "Matching recordings…"
                          : `${recordings.length} part${recordings.length === 1 ? "" : "s"} · matched by session date`}
                      </span>
                    </div>
                    {recordings.length > 0 ? (
                      <div className="mt-3 space-y-5">
                        {recordings.map((recording) => (
                          <div key={recording.component_id}>
                            <div className="flex items-center justify-between gap-3">
                              <p className="text-sm font-medium text-foreground">{recording.title}</p>
                              {recording.preview_url && (
                                <a
                                  href={recording.preview_url}
                                  target="_blank"
                                  rel="noreferrer"
                                  className="shrink-0 text-xs font-medium text-primary hover:underline"
                                >
                                  Open in new tab ↗
                                </a>
                              )}
                            </div>
                            {recording.week && <p className="text-xs text-muted-foreground">{recording.week}</p>}
                            {recording.preview_url && (
                              <div className="mt-2 aspect-video w-full overflow-hidden rounded-md border border-border bg-black/5">
                                <iframe
                                  src={recording.preview_url}
                                  title={recording.title}
                                  className="h-full w-full"
                                  loading="lazy"
                                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                  allowFullScreen
                                />
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    ) : (
                      !session.isLoading && (
                        <p className="mt-2 text-sm text-muted-foreground">
                          No recording is linked to this session date in the programme structure. Recordings are matched to a
                          session when an LMS lesson's title is dated to the session day and names the same course.
                        </p>
                      )
                    )}
                  </section>
                )}
                {activity.source_url && (
                  <section>
                    <div className="flex items-center justify-between">
                      <h2 className="label-caps">Activity content</h2>
                      <a
                        href={activity.source_url}
                        target="_blank"
                        rel="noreferrer"
                        className="text-xs font-medium text-primary hover:underline"
                      >
                        Open in new tab ↗
                      </a>
                    </div>
                    <div className="mt-2 aspect-video w-full overflow-hidden rounded-md border border-border bg-black/5">
                      <iframe
                        src={activity.source_url}
                        title={activity.activity_unit}
                        className="h-full w-full"
                        loading="lazy"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        allowFullScreen
                      />
                    </div>
                  </section>
                )}
                <section>
                  <h2 className="font-serif text-base text-foreground">Activity description</h2>
                  <p className="mt-2 text-sm leading-7 text-muted-foreground">{activity.activity_description || activity.activity_unit}</p>
                </section>
                <div className="grid gap-5 border-t border-border pt-5">
                  <section>
                    <h2 className="label-caps">Delivery and source</h2>
                    <p className="mt-2 text-sm text-foreground">{activity.delivery_method}</p>
                    <p className="mt-1 text-xs text-muted-foreground">{activity.source_course || activity.source_basis || "Programme structure"}</p>
                  </section>
                </div>
              </div>
            </article>

            <aside className="activity-snapshot overflow-hidden rounded-lg border border-border bg-card shadow-panel">
              <header className="bg-primary px-6 py-5 text-primary-foreground">
                <p className="snapshot-label label-caps">Activity snapshot</p>
                <h2 className="mt-1 font-serif text-xl font-bold text-primary-foreground">{activity.activity_unit}</h2>
              </header>
              <dl className="grid gap-5 px-6 py-6">
                <div>
                  <dt className="label-caps">Category</dt>
                  <dd className="mt-1 text-sm capitalize text-foreground">{activity.activity_category}</dd>
                </div>
                {activity.week && (
                  <div>
                    <dt className="label-caps">Lecture / week</dt>
                    <dd className="mt-1 text-sm text-foreground">{activity.week}</dd>
                  </div>
                )}
                <div>
                  <dt className="label-caps">Content creation time</dt>
                  <dd className="snapshot-value mt-1 font-mono">{formatDateTime(activity.created_at) ?? "Not recorded"}</dd>
                </div>
              </dl>

              {/* Real KSB mapping pulled live from programme_structure. */}
              <section className="border-t border-border px-6 py-6">
                <h3 className="label-caps">Mapped KSBs</h3>
                {activity.ksbs && activity.ksbs.length > 0 ? (
                  <ul className="mt-3 space-y-3">
                    {activity.ksbs.map((ksb, index) => (
                      <li key={`${ksb.code}-${index}`} className="rounded-md border border-border bg-background/40 px-3 py-2">
                        <div className="flex items-center gap-2">
                          <span className={`rounded-sm px-1.5 py-0.5 text-xs font-semibold ${ksbBadgeClass(ksb.type)}`}>{ksb.code}</span>
                          <span className="text-xs font-medium text-muted-foreground">{ksb.type_label}</span>
                        </div>
                        {ksb.description && (
                          <p className="mt-1.5 text-sm leading-6 text-foreground">{ksb.description}</p>
                        )}
                        {ksb.reason && (
                          <p className="mt-1 text-xs italic leading-5 text-muted-foreground">Why: {ksb.reason}</p>
                        )}
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p className="mt-2 text-sm text-muted-foreground">No KSBs mapped in programme structure.</p>
                )}
              </section>

              <div className="space-y-4 border-t border-border px-6 py-6">
                <label className="block">
                  <span className="label-caps">Planned hours</span>
                  <span className="mt-1.5 flex items-center gap-2">
                    <input
                      type="number"
                      step="0.25"
                      min="0"
                      value={plannedInput}
                      onChange={(event) => setPlannedInput(event.target.value)}
                      className="h-9 w-24 rounded-md border border-border bg-card px-2.5 text-sm text-foreground outline-none focus:border-primary"
                    />
                    <span className="text-xs text-muted-foreground">hours planned</span>
                  </span>
                  {activity.configured_duration && (
                    <span className="mt-1 block text-xs text-muted-foreground">Configured duration: {activity.configured_duration}</span>
                  )}
                  <span className="mt-2 block text-xs leading-5 text-muted-foreground">
                    Counts toward the minimum 20% off-the-job requirement. Logged time is compared against this planned duration at audit.
                  </span>
                </label>

                <label className="block">
                  <span className="label-caps">Auditor KSB notes (optional)</span>
                  <textarea
                    value={ksbsInput}
                    onChange={(event) => setKsbsInput(event.target.value)}
                    rows={3}
                    placeholder="Add notes or extra KSB mappings beyond those above…"
                    className="mt-1.5 w-full rounded-md border border-border bg-card px-2.5 py-2 text-sm text-foreground outline-none focus:border-primary"
                  />
                </label>

                <label className="block">
                  <span className="label-caps">Edited by (optional)</span>
                  <input
                    value={editorInput}
                    onChange={(event) => setEditorInput(event.target.value)}
                    placeholder="Your name"
                    className="mt-1.5 h-9 w-full rounded-md border border-border bg-card px-2.5 text-sm text-foreground outline-none focus:border-primary"
                  />
                </label>

                <div className="flex flex-wrap items-center gap-3">
                  <button
                    type="button"
                    onClick={() => saveAnnotation.mutate()}
                    disabled={!component || saveAnnotation.isPending}
                    className="rounded-md bg-primary px-3.5 py-1.5 text-sm font-medium text-primary-foreground hover:opacity-90 disabled:opacity-60"
                  >
                    {saveAnnotation.isPending ? "Saving…" : "Save"}
                  </button>
                  {saveAnnotation.isError && (
                    <span className="text-xs text-destructive">
                      {saveAnnotation.error instanceof Error ? saveAnnotation.error.message : "Save failed"}
                    </span>
                  )}
                  {!saveAnnotation.isError && annotation.data?.updated_at && (
                    <span className="text-xs text-muted-foreground">
                      Last saved {formatDateTime(annotation.data.updated_at)}
                      {annotation.data.updated_by ? ` by ${annotation.data.updated_by}` : ""}
                    </span>
                  )}
                </div>
              </div>
            </aside>
          </div>
        )}

        {isAttendance ? (
          <MreTable attendanceKey={activity?.plan_id} />
        ) : (
          <MreTable component={activity?.plan_id} learner={learner || undefined} />
        )}
        <p className="pb-4 text-xs text-muted-foreground">
          All values on this page are loaded from the Neon <span className="font-mono">Audit.learner_match</span> table.
        </p>
      </main>
    </div>
  );
}
